import{z as A,x as p,o as t,c as u,q as s,j as E,D as e,d as i,s as l,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"风险厌恶与阿罗–普拉特","description":"","frontmatter":{"title":"风险厌恶与阿罗–普拉特","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/risk-aversion.md","filePath":"econ/risk-aversion.md","lastUpdated":1791063341000}'),d={name:"econ/risk-aversion.md"};function _(B,a,m,h,c,C){const n=p("Mermaid");return t(),u("div",null,[a[2]||(a[2]=s('<h1 id="风险厌恶与阿罗–普拉特" tabindex="-1">风险厌恶与阿罗–普拉特 <a class="header-anchor" href="#风险厌恶与阿罗–普拉特" aria-label="Permalink to &quot;风险厌恶与阿罗–普拉特&quot;">​</a></h1><div class="epigraph"><p>绝对风险厌恶 $-u&#39;&#39;(w)/u&#39;(w)$ 度量为避开无穷小风险所要求的溢价；它在仿射变换下不变。</p><footer>—— 据 Pratt, Risk Aversion in the Small and in the Large, Econometrica, 1964；Arrow, Essays in the Theory of Risk-Bearing, 1971 整理</footer></div><p><a href="/econ/allais-independence">上一课</a>（阿莱悖论与独立性）。标明独立性在问卷上脆，但主干仍用 \\(\\mathbb{E}u\\)。本课不重讲阿莱四张彩票，也不再证明 vNM 表示。缺口是：有了伯努利 \\(u\\)，怎样比较「更厌恶风险」？仿射变换会改 \\(u&#39;&#39;\\)，不能直接看二阶导数的数字。必须找出在 \\(au+b\\) 下不变、又能对应风险溢价的局部测度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>风险厌恶的定义先不依赖微积分：对一切风险 \\(\\tilde\\varepsilon\\) 且 \\(\\mathbb{E}\\tilde\\varepsilon=0\\)，</p> \\[\\mathbb{E}\\,u(w+\\tilde\\varepsilon)\\le u(w). \\]<p>即确定的期望财富不差于风险本身。Jensen 不等式说这等价于 \\(u\\) 凹。凹是整体性质，后课保险、资产需求还要问「厌恶多少」以及「随财富如何变」。缺口是把凹性量化成一个函数 \\(r_A(w)\\)，使小风险的溢价 \\(\\pi\\) 满足 \\(\\pi\\approx\\tfrac12\\sigma^2 r_A(w)\\)。</p><p>Pratt 给出绝对风险厌恶 \\(r_A(w)=-u&#39;&#39;(w)/u&#39;(w)\\)，相对风险厌恶 \\(r_R(w)=-w u&#39;&#39;(w)/u&#39;(w)\\)。二者在正仿射变换下不变，这正用上了 vNM 的基数性。没有上一课钉死的仿射唯一性，这两个比没有定义。</p><p><span class="marginnote">数字实例：\\(r_A\\) 的量纲是「每元财富」。若 \\(r_A=0.001\\)，面对标准差 200 元（方差 \\(\\sigma^2=40000\\)）的小风险，确定性等价的损失约 \\(\\tfrac12\\times40000\\times0.001=20\\) 元——为了把 ±200 元的波动抹平，这个人最多愿意少拿 20 元确定收入。</span></p><h3 id="小风险溢价是局部-大风险要整体凹" tabindex="-1">小风险溢价是局部，大风险要整体凹 <a class="header-anchor" href="#小风险溢价是局部-大风险要整体凹" aria-label="Permalink to &quot;小风险溢价是局部，大风险要整体凹&quot;">​</a></h3><p>二阶泰勒把小噪声的确定性等价值写成方差乘 \\(r_A\\)。大风险不能只看一点的 \\(r_A\\)：Pratt 证明 \\(r_A\\) 处处更大当且仅当对一切风险要求更高溢价。局部测度与全局比较在这个意义上对齐。本课不把各种 \\(u\\) 的函数形式列成表，只钉比较原则。</p><p><span class="marginnote">DARA（\\(r_A\\) 随财富下降）意味着风险资产是正常品：更富则多持绝对风险。CRRA 常作基准，不是经验定律。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定两次可微、严格递增的 \\(u\\)，计算 \\(r_A\\)、\\(r_R\\)。比较两个决策者：若 \\(r_A^1(w)\\ge r_A^2(w)\\) 对一切 \\(w\\)，则 1 对同一风险的溢价更高，且 1 的 \\(u\\) 是 2 的凹变换。这是 Pratt 的等价刻画，把「更凹」从任意单调凹变换里收成可比的一条。</p><p>保险：公平保费下，严格风险厌恶者充分投保。不公平加载下，最优留下正的保留风险，\\(r_A\\) 决定自留多少。本课只写到这个接口；最优保单的形态还要随机占优与状态依存才能说清。</p>',15)),(t(),E(o,null,{default:e(()=>[l(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22vNM%20%E6%95%88%E7%94%A8%20E%20u%22%5D%20--%3E%20CONC%5B%22%E5%87%B9%E6%80%A7%20%3D%20%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%22%5D%0A%20%20CONC%20--%3E%20RA%5B%22r_A%20%3D%20-u''%2Fu'%22%5D%0A%20%20RA%20--%3E%20PI%5B%22%E5%B0%8F%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%20%E2%89%88%20%C2%BD%20%CF%83%C2%B2%20r_A%22%5D%0A%20%20RA%20--%3E%20CMP%5B%22r_A%20%E6%9B%B4%E5%A4%A7%20%3D%20%E5%85%A8%E5%B1%80%E6%9B%B4%E5%8E%8C%E6%81%B6%22%5D%0A%20%20CMP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B8%8D%E6%8C%87%E5%AE%9A%20u%20%E7%9A%84%E5%8D%A0%E4%BC%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"期望值—方差分析只在 \\(u\\) 二次或风险无穷小时与 \\(r_A\\) 一致。二次效用有递增的 \\(r_A\\) 且存在餍足，主干不当成一般风险偏好。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"\\(r_A\\) 把「弯曲程度」从刻度里抽出来：\\(u'\\) 在分母上抵消仿射因子，\\(u''\\) 的符号给出凹凸。财富进入 \\(r_R\\)，因为同一绝对噪声对穷人更重。后课资产定价若写 CRRA，其实是在选一条 \\(r_R\\) 为常数的伯努利函数，以便加总或写欧拉方程；那是宏观课的用法，本课只提供这个函数从哪来。",-1)),a[6]||(a[6]=r("p",null,[r("span",{class:"marginnote"},"直觉类比：把 \\(u(w)\\) 想成一条越爬越平缓的山路——财富越多，多一块钱带来的快感越淡（边际效用递减）。风险厌恶量的是这条路的「弯度」：弯得越厉害，越不肯拿确定的钱去换赌局；仿射变换只是把整条路上下拉伸平移，弯度不变。")],-1)),(t(),E(o,null,{default:e(()=>[l(n,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E6%95%88%E7%94%A8%20u(w)%22%5D%20--%3E%20T%5B%22%E6%8D%A2%E6%88%90%20a%C2%B7u(w)%2Bb%22%5D%0A%20%20T%20--%3E%20N%5B%22%E5%88%86%E5%AD%90%20u''%20%E5%8F%98%E6%88%90%20a%C2%B7u''%22%5D%0A%20%20T%20--%3E%20D%5B%22%E5%88%86%E6%AF%8D%20u'%20%E5%8F%98%E6%88%90%20a%C2%B7u'%22%5D%0A%20%20N%20--%3E%20R%5B%22%E6%AF%94%E5%80%BC%E9%87%8C%E7%9A%84%20a%20%E7%BA%A6%E6%8E%89%22%5D%0A%20%20D%20--%3E%20R%0A%20%20R%20--%3E%20INV%5B%22r_A%20%E4%B8%8D%E5%8F%98%EF%BC%9A%E5%8E%8C%E6%81%B6%E5%BC%BA%E5%BA%A6%E4%B8%8E%E6%95%88%E7%94%A8%E5%88%BB%E5%BA%A6%E6%97%A0%E5%85%B3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>与阿莱的关系：凹性是 vNM 内部的形状，独立性是表示能否成立。问卷违背独立性时，\\(r_A\\) 随框架变，测到的不是稳定的风险态度。市场与保险理论仍按凹 \\(u\\) 走，是规范与工作假说，不是对阿莱的否定。</p><p><span class="marginnote">不要把 \\(r_A\\) 写成限价簿里的风险限额。微观结构的库存风险是量化栏的对象；这里是状态上的财富效用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(r_A\\) 需要二阶可微。折拐的 \\(u\\)（例如分段线性）仍可风险厌恶，但局部溢价公式失效，要用超微分。多维风险、背景风险会改变有效 \\(r_A\\)，本课不展开。也不处理模糊厌恶：概率未知时没有 \\(\\mathbb{E}u\\) 可凹。</p><p><span class="marginnote">常见误区：不是「讨厌输钱」就叫风险厌恶。定义只看确定性等价——只要对一切零均值风险都有 \\(\\mathbb{E}u(w+\\tilde\\varepsilon)\\lt u(w)\\)，就是厌恶。一个人可以既喜欢买彩票又买保险（凹凸混合），那已经超出单一凹 \\(u\\) 能描述的范围。</span></p><p>随机占优下一课要问：不指定某一个 \\(u\\)，只知道一类凹函数，能否给分布排序。那是把本课的「给定 \\(u\\)」放宽成「所有风险厌恶者」。</p><p>背景风险、不可保的劳动收入，会改变有效 \\(r_A\\)：人对可交易风险的态度不再等于实验室里的 \\(u\\)。本课只在单一财富风险上定义测度。也不把 \\(r_A\\) 写成做市商的库存惩罚——那是量化栏。</p><p>后课默认：风险厌恶即 \\(u\\) 凹，强度用 Arrow–Pratt 比较。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>风险厌恶等价于伯努利函数凹；强度用 \\(r_A\\)、\\(r_R\\)，仿射不变。</li><li>小风险溢价由方差与 \\(r_A\\) 决定；全局比较靠 \\(r_A\\) 点点更大。</li><li>公平保险充分投保；加载下自留风险由 \\(r_A\\) 调节。</li><li>阿莱打的是独立性，不是凹性本身。</li><li>出处：Pratt, <em>Econometrica</em>, 1964；Arrow, <em>Essays in the Theory of Risk-Bearing</em>；Mas-Colell, Whinston and Green 第 6 章。</li></ul>',10))])}const f=A(d,[["render",_]]);export{b as __pageData,f as default};
